command:
if (!game.wfrp4eMutationRoll) {
    ui.notifications.error("Mutation Roll Function not found. Ensure the world script is loaded.");
    return;
}

const actors = game.actors.contents;
const folders = game.folders.filter(f => f.type === "Actor");

if (!actors.length) {
    ui.notifications.warn("No actors available to select.");
    return;
}

const folderOptions = folders.reduce((html, folder) => {
    return html + `<option value='${folder.id}'>${folder.name}</option>`;
}, "<option value='all'>All Actors</option>");

function getActorsByFolder(folderId) {
    return actors.filter(actor => folderId === "all" || actor.folder?.id === folderId);
}

function updateActorDropdown(html, folderId) {
    const actorSelect = html.find("#actor-select");
    const filteredActors = getActorsByFolder(folderId);
    actorSelect.html(filteredActors.map(actor => `<option value='${actor.id}'>${actor.name}</option>`).join(""));
}

new Dialog({
    title: "Dissolution of Body and Mind",
    content: `
        <form>
            <div class="form-group">
                <label for="folder-select">Select Folder:</label>
                <select id="folder-select" name="folder">
                    ${folderOptions}
                </select>
            </div>
            <div class="form-group">
                <label for="actor-select">Select Actor:</label>
                <select id="actor-select" name="actor">
                    ${actors.map(actor => `<option value='${actor.id}'>${actor.name}</option>`).join("")}
                </select>
            </div>
            <div class="form-group">
                <label>Mutation Type</label>
                <div class="form-fields">
                    <select id="mutation-type" name="mutation-type">
                        <option value="all">All</option>
                        <option value="khorne">Khorne</option>
                        <option value="tzeentch">Tzeentch</option>
                        <option value="slaanesh">Slaanesh</option>
                        <option value="nurgle">Nurgle</option>
                        <option value="necromancy">Necromancy</option>
                    </select>
                </div>
            </div>
        </form>
    `,
    render: (html) => {
        html.find("#folder-select").change(event => {
            updateActorDropdown(html, event.target.value);
        });
    },
    buttons: {
        roll: {
            label: "Roll Mutation",
            callback: (html) => {
                const selectedActor = game.actors.get(html.find("#actor-select").val());
                const selectedMutationSource = html.find("#mutation-type").val();
                if (selectedActor) {
                    game.wfrp4eMutationRoll(selectedActor, selectedMutationSource);
                } else {
                    ui.notifications.error("Invalid actor selection.");
                }
            }
        },
        cancel: { label: "Cancel" }
    },
    default: "roll"
}).render(true);
